/**
 * Laya Feed Control - Bluesky Platform Adapter
 * Covers Bluesky AT Protocol Web Client Feeds
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class BlueskyAdapter extends BasePlatformAdapter {
  readonly name = 'bluesky';
  readonly supportedRoutes = [
    /(?:www\.)?bsky\.app\/(?:$|\?|profile\/)/,
  ];

  public getFeedType(url: URL): FeedType {
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div[data-testid^="feedItem"]',
      'div[data-testid="postThreadItem"]',
      'div[role="link"][data-testid*="post"]',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const textEl = element.querySelector<HTMLElement>('div[data-testid="postText"], div[dir="auto"]');
    const text = textEl?.textContent?.trim() || '';

    // Author
    const authorEl = element.querySelector<HTMLElement>(
      'a[data-testid="feedItem-author"], span[data-testid="author-handle"]'
    );
    const authorHandle = authorEl?.textContent?.trim().replace(/^@/, '') || 'bsky_user';

    const linkEl = element.querySelector<HTMLAnchorElement>('a[href*="/post/"]');
    const href = linkEl?.getAttribute('href') || '';
    const idMatch = href.match(/\/post\/([a-zA-Z0-9]+)/);
    const postId = idMatch ? idMatch[1] : `bsky_${authorHandle}_${text.slice(0, 15)}`;

    if (!text && !element.querySelector('img, video')) return null;

    return {
      id: postId,
      url: href.startsWith('http') ? href : `https://bsky.app${href}`,
      author: {
        name: authorHandle,
        handle: authorHandle,
      },
      text: text || 'Bluesky Post',
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'text',
      element,
    };
  }
}
