/**
 * Laya Feed Control - Threads Platform Adapter
 * Covers Threads Feed and Post Cards
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class ThreadsAdapter extends BasePlatformAdapter {
  readonly name = 'threads';
  readonly supportedRoutes = [
    /(?:www\.)?threads\.net\/(?:$|\?|@[\w.-]+)/,
  ];

  public getFeedType(url: URL): FeedType {
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div[data-pressable-container="true"]',
      'div.x1a2a7pz',
      'article',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const textEls = element.querySelectorAll<HTMLElement>('div[dir="auto"] span');
    let text = '';
    textEls.forEach((el) => {
      const c = el.textContent?.trim();
      if (c && c.length > text.length) text = c;
    });

    if (!text && !element.querySelector('video, img')) return null;

    // Author
    const authorEl = element.querySelector<HTMLElement>('a[role="link"] span[dir="auto"]');
    const authorHandle = authorEl?.textContent?.trim().replace(/^@/, '') || 'threads_user';

    const postId = `threads_${authorHandle}_${text.slice(0, 15)}_${Math.random().toString(36).slice(2, 6)}`;

    return {
      id: postId,
      author: {
        name: authorHandle,
        handle: authorHandle,
      },
      text: text || 'Threads Post',
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'text',
      element,
    };
  }
}
