/**
 * Laya Feed Control - YouTube Platform Adapter
 * Covers Home, Search, Subscriptions, and Shorts
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class YouTubeAdapter extends BasePlatformAdapter {
  readonly name = 'youtube';
  readonly supportedRoutes = [
    /(?:www\.)?youtube\.com\/(?:$|\?|results|feed\/subscriptions|shorts\/)/,
  ];

  public getFeedType(url: URL): FeedType {
    if (url.pathname.startsWith('/shorts')) {
      return 'shorts';
    }
    if (url.pathname.startsWith('/results')) {
      return 'search';
    }
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'ytd-rich-item-renderer',
      'ytd-video-renderer',
      'ytd-grid-video-renderer',
      'ytd-compact-video-renderer',
      'ytd-reel-video-renderer', // Shorts viewer
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const isShorts = element.tagName.toLowerCase() === 'ytd-reel-video-renderer';

    // Title / Text
    let titleEl: HTMLElement | null = null;
    if (isShorts) {
      titleEl = element.querySelector<HTMLElement>('h2.title, yt-shorts-video-title, #title');
    } else {
      titleEl = element.querySelector<HTMLElement>('#video-title, #video-title-link, h3');
    }

    const titleText = titleEl?.textContent?.trim() || '';
    if (!titleText && !isShorts) {
      return null;
    }

    // Author / Channel
    const channelEl = element.querySelector<HTMLElement>(
      '#channel-name, ytd-channel-name, .ytd-channel-name, #text.ytd-channel-name'
    );
    const authorName = channelEl?.textContent?.trim() || 'Unknown Channel';
    const authorHandle = authorName.replace(/\s+/g, '_');

    // Video URL & ID
    const linkEl = element.querySelector<HTMLAnchorElement>('a#thumbnail, a#video-title-link, a[href*="/watch"], a[href*="/shorts"]');
    const href = linkEl?.getAttribute('href') || '';
    const idMatch = href.match(/(?:v=|shorts\/)([a-zA-Z0-9_-]{11})/);
    const postId = idMatch ? idMatch[1] : `yt_${titleText.slice(0, 20)}_${Math.random().toString(36).slice(2, 7)}`;

    return {
      id: postId,
      url: href.startsWith('http') ? href : `https://www.youtube.com${href}`,
      author: {
        name: authorName,
        handle: authorHandle,
      },
      text: titleText,
      hashtags: this.extractHashtags(titleText),
      mediaType: 'video',
      element,
    };
  }

  public async advanceShort(currentElement: HTMLElement): Promise<boolean> {
    this.pauseMedia(currentElement);

    // Try native next button
    const nextBtn = document.querySelector<HTMLButtonElement>(
      '#navigation-button-down button, ytd-shorts-player-controls #navigation-button-down'
    );
    if (nextBtn) {
      nextBtn.click();
      return true;
    }

    // Fallback: keyboard arrow down
    this.dispatchArrowDown();
    return true;
  }
}
