/**
 * Laya Feed Control - Facebook Platform Adapter
 * Covers Feed, Watch, and Reels
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class FacebookAdapter extends BasePlatformAdapter {
  readonly name = 'facebook';
  readonly supportedRoutes = [
    /(?:www\.)?facebook\.com\/(?:$|\?|reel\/|watch|groups)/,
  ];

  public getFeedType(url: URL): FeedType {
    if (url.pathname.includes('/reel/')) {
      return 'shorts';
    }
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div[data-pagelet^="FeedUnit"]',
      'div[role="feed"] > div',
      'div.x1yztbdb', // Primary FB feed unit class
      'div[role="article"]',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    // Post text
    const textEls = element.querySelectorAll<HTMLElement>('div[dir="auto"]');
    let text = '';
    textEls.forEach((el) => {
      const content = el.textContent?.trim();
      if (content && content.length > text.length) {
        text = content;
      }
    });

    if (!text && !element.querySelector('video')) {
      return null;
    }

    // Author
    const authorEl = element.querySelector<HTMLElement>('h4 a, strong, a.x1i10hfl[role="link"]');
    const authorName = authorEl?.textContent?.trim() || 'Facebook User';
    const authorHandle = authorName.replace(/\s+/g, '_');

    // Post ID
    const postId = `fb_${element.getAttribute('data-pagelet') || Math.random().toString(36).slice(2, 9)}`;

    return {
      id: postId,
      author: {
        name: authorName,
        handle: authorHandle,
      },
      text: text || 'Facebook Post',
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'image',
      element,
    };
  }

  public async advanceShort(currentElement: HTMLElement): Promise<boolean> {
    this.pauseMedia(currentElement);
    this.dispatchArrowDown();
    return true;
  }
}
