/**
 * Laya Feed Control - TikTok Platform Adapter
 * Covers TikTok Vertical Web Feed
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class TikTokAdapter extends BasePlatformAdapter {
  readonly name = 'tiktok';
  readonly supportedRoutes = [
    /(?:www\.)?tiktok\.com\/(?:$|\?|foryou|following|@[\w.-]+\/video)/,
  ];

  public getFeedType(url: URL): FeedType {
    return 'shorts';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div[data-e2e="feed-item"]',
      'div[data-e2e="recommend-list-item-container"]',
      'div.css-1m2595h-DivItemContainer',
      'section[data-e2e="video-feed"] > div',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const descEl = element.querySelector<HTMLElement>(
      'div[data-e2e="video-desc"], h1[data-e2e="browse-video-desc"], div.css-169fq0e-DivContainer'
    );
    const text = descEl?.textContent?.trim() || '';

    // Author
    const authorEl = element.querySelector<HTMLElement>(
      'a[data-e2e="video-author-uniqueid"], span[data-e2e="video-author-uniqueid"]'
    );
    const authorHandle = authorEl?.textContent?.trim().replace(/^@/, '') || 'tiktoker';

    const postId = `tt_${authorHandle}_${text.slice(0, 15)}_${Math.random().toString(36).slice(2, 6)}`;

    return {
      id: postId,
      author: {
        name: authorHandle,
        handle: authorHandle,
      },
      text: text || 'TikTok Video',
      hashtags: this.extractHashtags(text),
      mediaType: 'video',
      element,
    };
  }

  public async advanceShort(currentElement: HTMLElement): Promise<boolean> {
    this.pauseMedia(currentElement);

    // Try native next button
    const nextBtn = document.querySelector<HTMLButtonElement>(
      'button[data-e2e="arrow-right"], button[aria-label="Next video"]'
    );
    if (nextBtn) {
      nextBtn.click();
      return true;
    }

    this.dispatchArrowDown();
    return true;
  }
}
