/**
 * Laya Feed Control - Real-Time Multilingual Obfuscation-Resistant Abuse Detector
 * Capable of detecting abuse across English, Hindi, Hinglish, Indic, European, and World languages
 * Even with obfuscated structures like "ma*ar", "m@d@r", "f*ck", "ch**iya", "b.c", "b*tch", etc.
 */

import { AbuseAssessment } from '../types';

export interface AbuseScanOptions {
  strictness?: 'lenient' | 'balanced' | 'strict';
  obfuscationDefense?: boolean;
  customWords?: string[];
  exemptWords?: string[];
}

/**
 * Homoglyph mapping: lookalike Cyrillic/Greek/symbols mapped to standard Latin/ASCII
 */
const HOMOGLYPHS: Record<string, string> = {
  // Cyrillic lookalikes
  'а': 'a', 'А': 'A', 'в': 'b', 'В': 'B', 'е': 'e', 'Е': 'E',
  'к': 'k', 'К': 'K', 'м': 'm', 'М': 'M', 'н': 'h', 'Н': 'H',
  'о': 'o', 'О': 'O', 'р': 'p', 'Р': 'P', 'с': 'c', 'С': 'C',
  'т': 't', 'Т': 'T', 'у': 'y', 'У': 'Y', 'х': 'x', 'Х': 'X',
  // Greek lookalikes
  'α': 'a', 'β': 'b', 'ε': 'e', 'ι': 'i', 'κ': 'k', 'ν': 'v',
  'ο': 'o', 'ρ': 'p', 'τ': 't', 'υ': 'u', 'χ': 'x',
};

/**
 * Leetspeak & symbol substitution map
 */
const LEETSPEAK_MAP: Record<string, string> = {
  '@': 'a',
  '4': 'a',
  '8': 'b',
  '3': 'e',
  '!': 'i',
  '1': 'i',
  '|': 'i',
  '0': 'o',
  '$': 's',
  '5': 's',
  '7': 't',
  '+': 't',
};

/**
 * Words that could falsely trigger abuse detectors (Scunthorpe problem prevention)
 */
const SAFE_WORDS = new Set([
  'mature', 'maturity', 'matrix', 'matter', 'master', 'mastery', 'match', 'matches',
  'maternity', 'madagascar', 'madam', 'madison', 'madrigal', 'madrid',
  'pass', 'passed', 'passion', 'passive', 'passport',
  'classic', 'classical', 'class', 'classes', 'classroom',
  'assistant', 'assist', 'assisting', 'assistance',
  'therapist', 'constitution', 'document', 'documents', 'cucumber',
  'cocktail', 'cocktails', 'peacock', 'peacocks',
  'title', 'titles', 'titular', 'entity', 'identities',
  'mass', 'massive', 'grass', 'brass', 'bass', 'basset',
  'butter', 'button', 'buttons', 'bitter', 'shuttle', 'sheet', 'sheets',
  'shirt', 'shirts', 'ship', 'shipping', 'association', 'associates',
  'analytic', 'analytics', 'banana', 'canal', 'canals', 'scrap', 'scraps'
]);

export class ObfuscationNormalizer {
  /**
   * Normalizes text by removing zero-width characters, resolving homoglyphs,
   * decoding leetspeak, collapsing character repetitions, and stripping diacritics.
   */
  public static normalize(text: string): string {
    if (!text) return '';

    // 1. Unicode NFKD normalization
    let s = text.normalize('NFKD');

    // 2. Strip zero-width & invisible characters
    s = s.replace(/[\u200B-\u200D\uFEFF\u00AD\u2060\u180E]/g, '');

    // 3. Map homoglyphs
    let homoglyphClean = '';
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      homoglyphClean += HOMOGLYPHS[ch] || ch;
    }
    s = homoglyphClean;

    // 4. Strip combining diacritical marks (e.g. pútá -> puta, cabrón -> cabron)
    s = s.replace(/[\u0300-\u036f]/g, '');

    // Convert to lowercase for unified matching
    s = s.toLowerCase();

    // 5. Decode leetspeak symbols to letters
    let leetClean = '';
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      leetClean += LEETSPEAK_MAP[ch] || ch;
    }
    s = leetClean;

    // 6. Collapse runs of identical consecutive characters (e.g. fuuuuck -> fuck, maaaadaaar -> madar)
    s = s.replace(/(.)\1+/g, '$1');

    return s;
  }

  /**
   * Generates a compressed version stripped of internal punctuation/spacing
   * e.g. "m.a.d.a.r" -> "madar", "b-h-e-n" -> "bhen"
   */
  public static stripSeparators(text: string): string {
    return text.replace(/[\s\.\-_\\/\*\+\^,;:#~!@$%&]+/g, '');
  }
}

/**
 * Core Abuse Pattern Rule definition
 */
interface AbuseRule {
  id: string;
  pattern: RegExp;
  category: 'obfuscated' | 'hindi_indic' | 'english' | 'multilingual';
  baseTerm: string;
  severity: number; // 0.1 to 1.0
}

export class AbuseDetector {
  private rules: AbuseRule[] = [];
  private devanagariRules: AbuseRule[] = [];
  private exactBlockedTerms: Set<string> = new Set();
  private exemptTerms: Set<string> = new Set();

  constructor() {
    this.initRules();
  }

  private initRules(): void {
    // --------------------------------------------------------------------
    // 1. OBFUSCATED & STRUCTURED PATTERNS (e.g. ma*ar, ch**iya, f*ck, etc.)
    // --------------------------------------------------------------------
    this.rules.push(
      // Specifically handles "ma*ar", "m@d@r", "m*ther", "madar", "madarchod"
      {
        id: 'obf_madar',
        // Matches ma*ar, ma**r, m*dar, m@d@r, m.a.d.a.r, madar, madarchod, madarch*d, etc.
        pattern: /\b(m[a4@*]+[*x#@$%!._\-\s]*[a4@*]*[d*]*[a4@*]*r+(?:[c*]*h*[o0*]*[d*]+)?)\b/i,
        category: 'obfuscated',
        baseTerm: 'madar',
        severity: 0.98,
      },
      // Direct regex specifically targeting "ma*ar", "ma*r", "m**ar"
      {
        id: 'spec_ma_star_ar',
        pattern: /\bm[a4@*]+[*_.\-\s#@$%]+[a4@*]*r\b/i,
        category: 'obfuscated',
        baseTerm: 'ma*ar',
        severity: 0.99,
      },
      // Matches "ch**iya", "chutiya", "ch*tiya", "chootiya"
      {
        id: 'obf_chutiya',
        pattern: /\b(ch+[o0u*]+[*x#@$%!._\-\s]*t+[i!1*]*y+[a4@*]+(?:g+[i!1]*r+[i!1]*)?)\b/i,
        category: 'obfuscated',
        baseTerm: 'chutiya',
        severity: 0.95,
      },
      // Direct regex targeting "ch**iya", "ch*ya", "ch**ya"
      {
        id: 'spec_ch_star_iya',
        pattern: /\bch+[*_.\-\s#@$%]+(?:[i!1]*y+[a4@*]+|t+[i!1*]*y+[a4@*]+)\b/i,
        category: 'obfuscated',
        baseTerm: 'ch**iya',
        severity: 0.99,
      },
      // Matches "bhenchod", "behenchod", "bh*nchod", "bhench*d", "b*enchod"
      {
        id: 'obf_bhenchod',
        pattern: /\b(b+[e3*]*h+[e3*]*n+[*x#@$%!._\-\s]*c+h+[o0*]+d+)\b/i,
        category: 'obfuscated',
        baseTerm: 'bhenchod',
        severity: 0.98,
      },
      // Matches "bhosdike", "bhosadike", "bsdk", "b.s.d.k"
      {
        id: 'obf_bhosdike',
        pattern: /\b(bh+[o0*]+s+[a4@*]*d+[i!1*]*k+[e3*]*|b[\s._\-]*s[\s._\-]*d[\s._\-]*k)\b/i,
        category: 'obfuscated',
        baseTerm: 'bhosdike',
        severity: 0.98,
      },
      // Matches "bkl", "b.k.l", "bhen ke lode"
      {
        id: 'obf_bkl',
        pattern: /\b(b[\s._\-]*k[\s._\-]*l|b+h+e+n+\s+k+[e3]*\s+l+[o0u]+d+[e3]*)\b/i,
        category: 'obfuscated',
        baseTerm: 'bkl',
        severity: 0.95,
      },
      // Matches "mc", "m.c", "bc", "b.c", "mkc", "tmkc"
      {
        id: 'obf_indic_acronyms',
        pattern: /\b(m[\s._\-]*c|b[\s._\-]*c|m[\s._\-]*k[\s._\-]*c|t[\s._\-]*m[\s._\-]*k[\s._\-]*c)\b/i,
        category: 'obfuscated',
        baseTerm: 'mc/bc',
        severity: 0.90,
      },
      // Matches "gaandu", "gandu", "gaand", "g*ndu"
      {
        id: 'obf_gandu',
        pattern: /\b(g+[a4@*]+[a4@*]*n+d+[u0o*]+)\b/i,
        category: 'obfuscated',
        baseTerm: 'gandu',
        severity: 0.95,
      },
      // Matches "harami", "haramzada", "haramkhor"
      {
        id: 'obf_harami',
        pattern: /\b(h+[a4@*]+r+[a4@*]+m+[i!1*]+|h+[a4@*]+r+[a4@*]+m+z+[a4@*]+d+[a4@*]+)\b/i,
        category: 'obfuscated',
        baseTerm: 'harami',
        severity: 0.90,
      },
      // Matches "randi", "raand", "r*ndi"
      {
        id: 'obf_randi',
        pattern: /\b(r+[a4@*]+[a4@*]*n*d+[i!1*]+|r+[a4@*]+[a4@*]*n+d+)\b/i,
        category: 'obfuscated',
        baseTerm: 'randi',
        severity: 0.98,
      },
      // Matches "lauda", "lawda", "loda", "lund", "l*nd"
      {
        id: 'obf_lauda',
        pattern: /\b(l+[a4@*o0]*[uw]*d+[a4@*]+|l+[u*]+n+d+)\b/i,
        category: 'obfuscated',
        baseTerm: 'lauda/lund',
        severity: 0.95,
      },

      // --------------------------------------------------------------------
      // 2. ENGLISH PROFANITY & OBFUSCATED SLURS
      // --------------------------------------------------------------------
      // Matches "f*ck", "f**k", "f.u.c.k", "fuck", "fucker", "fucking", "m*therf*cker"
      {
        id: 'eng_fuck',
        pattern: /\b(f+[*x#@$%!._\-\s]*[u*]+[*x#@$%!._\-\s]*c+[*x#@$%!._\-\s]*k+(?:e+r+|i+n+g+|s+)?|f+[*x#@$%!._\-\s]+k+)\b/i,
        category: 'english',
        baseTerm: 'fuck',
        severity: 0.96,
      },
      // Matches "b*tch", "b!tch", "b.i.t.c.h", "bitch", "bitches"
      {
        id: 'eng_bitch',
        pattern: /\b(b+[*x#@$%!._\-\s]*[i!1*]+[*x#@$%!._\-\s]*t+[*x#@$%!._\-\s]*c+[*x#@$%!._\-\s]*h+(?:e+s+)?|b+[*x#@$%!._\-\s]+t+c+h+)\b/i,
        category: 'english',
        baseTerm: 'bitch',
        severity: 0.94,
      },
      // Matches "b*stard", "bastard"
      {
        id: 'eng_bastard',
        pattern: /\b(b+[*x#@$%!._\-\s]*[a4@*]+[*x#@$%!._\-\s]*s+[*x#@$%!._\-\s]*t+[*x#@$%!._\-\s]*a+r+d+(?:s+)?|b+[*x#@$%!._\-\s]+s+t+a+r+d+)\b/i,
        category: 'english',
        baseTerm: 'bastard',
        severity: 0.92,
      },
      // Matches "asshole", "a$$hole", "a**hole" (strictly avoids "pass", "classic", "assistant")
      {
        id: 'eng_asshole',
        pattern: /\b(a+[*$s@#]{2,}h+[o0]+l+[e3]+|a+s+s+h+[o0]+l+[e3]+)\b/i,
        category: 'english',
        baseTerm: 'asshole',
        severity: 0.92,
      },
      // Matches "c*nt", "cunt"
      {
        id: 'eng_cunt',
        pattern: /\b(c+[*x#@$%!._\-\s]*[u*]+[*x#@$%!._\-\s]*n+[*x#@$%!._\-\s]*t+)\b/i,
        category: 'english',
        baseTerm: 'cunt',
        severity: 0.99,
      },
      // Matches "d*ck", "dick" (requires word boundary, avoids dictionary collisions)
      {
        id: 'eng_dick',
        pattern: /\b(d+[*x#@$%!._\-\s]*[i!1*]+[*x#@$%!._\-\s]*c+[*x#@$%!._\-\s]*k+(?:h+e+a+d+)?)\b/i,
        category: 'english',
        baseTerm: 'dick',
        severity: 0.88,
      },
      // Matches severe hate speech slurs
      {
        id: 'eng_hate_slurs',
        pattern: /\b(n+[i!1*]+g+g+[e3a*]+r*|f+[a4@*]+g+g+[o0*]+t+|r+[e3*]+t+[a4@*]+r+d+)\b/i,
        category: 'english',
        baseTerm: 'slur',
        severity: 1.0,
      },

      // --------------------------------------------------------------------
      // 3. MULTILINGUAL (Spanish, French, German, Russian, etc.)
      // --------------------------------------------------------------------
      // Spanish: puta, hijo de puta, mierda, pendejo, cabrón, maricón, coño
      {
        id: 'ml_spanish',
        pattern: /\b(p+[u*]+t+[a4@*]+|h+i+j+[o0]+\s+d+e+\s+p+u+t+a|m+i+e+r+d+a|p+e+n+d+e+j+[o0a4]+|c+a+b+r+[o0]+n+|m+a+r+i+c+[o0]+n+|c+[o0]+n+[o0]+)\b/i,
        category: 'multilingual',
        baseTerm: 'spanish_abuse',
        severity: 0.92,
      },
      // French: putain, merde, salope, connard, fils de pute, encule
      {
        id: 'ml_french',
        pattern: /\b(p+u+t+a+i+n+|m+e+r+d+e+|s+a+l+[o0*]+p+e+|c+[o0*]+n*[*_.\-\s#@$%]*n*a+r+d+|f+i+l+s+\s+d+e+\s+p+u+t+e+|e+n+c+u+l+e+)\b/i,
        category: 'multilingual',
        baseTerm: 'french_abuse',
        severity: 0.92,
      },
      // German: arschloch, hurensohn, fotze, scheisse, wichser, schlampe
      {
        id: 'ml_german',
        pattern: /\b(a+r+s+c+h+l+[o0]+c+h+|h+u+r+e+n+s+[o0]+h+n+|f+[o0]+t+z+e+|s+c+h+e+i+s+s+e+|w+i+c+h+s+e+r+|s+c+h+l+a+m+p+e+)\b/i,
        category: 'multilingual',
        baseTerm: 'german_abuse',
        severity: 0.92,
      },
      // Russian transliterated: suka, blyat, huy, pizda, pizdec, nahuy
      {
        id: 'ml_russian_translit',
        pattern: /\b(s+u+k+a+|b+l+y+a+t+|h+u+y+|p+i+z+d+a+|p+i+z+d+e+c+|n+a+h+u+y+)\b/i,
        category: 'multilingual',
        baseTerm: 'russian_abuse',
        severity: 0.94,
      }
    );

    // --------------------------------------------------------------------
    // 4. DEVANAGARI SCRIPT RULES (Hindi, Marathi, Nepali)
    // --------------------------------------------------------------------
    this.devanagariRules.push(
      // मादरचोद, मादर***, मा*ार
      {
        id: 'dev_madarchod',
        pattern: /मा(?:दर|[\*x#_.\-\s]+)?(?:चोद|[\*x#_.\-\s]+)?/,
        category: 'hindi_indic',
        baseTerm: 'मादरचोद',
        severity: 0.99,
      },
      // बहनचोद, भेंचोद
      {
        id: 'dev_bhenchod',
        pattern: /(?:बहन|भें|भेन)(?:[\*x#_.\-\s]+)?चोद/,
        category: 'hindi_indic',
        baseTerm: 'बहनचोद',
        severity: 0.99,
      },
      // चूतिया, चू**या
      {
        id: 'dev_chutiya',
        pattern: /चू(?:ति|[\*x#_.\-\s]+)या/,
        category: 'hindi_indic',
        baseTerm: 'चूतिया',
        severity: 0.98,
      },
      // भोसड़ीके, भोसड़ी, भोसडीके
      {
        id: 'dev_bhosdike',
        pattern: /भोस[ड़ड]ी(?:के)?/,
        category: 'hindi_indic',
        baseTerm: 'भोसड़ीके',
        severity: 0.99,
      },
      // गांडू, गाँडू, गांड
      {
        id: 'dev_gandu',
        pattern: /गा[ंँ]?डू/,
        category: 'hindi_indic',
        baseTerm: 'गांडू',
        severity: 0.98,
      },
      // हरामी, हरामखोर
      {
        id: 'dev_harami',
        pattern: /हरामी|हरामखोर/,
        category: 'hindi_indic',
        baseTerm: 'हरामी',
        severity: 0.95,
      },
      // रंडी, रांड
      {
        id: 'dev_randi',
        pattern: /रंडी|रांड/,
        category: 'hindi_indic',
        baseTerm: 'रंडी',
        severity: 0.98,
      },
      // लौड़ा, लौड़े, लंड
      {
        id: 'dev_lauda',
        pattern: /लौ[ड़ड][ाे]|ल[ंन्]ड/,
        category: 'hindi_indic',
        baseTerm: 'लौड़ा/लंड',
        severity: 0.98,
      },
      // कुतिया, कुत्ता
      {
        id: 'dev_kutiya',
        pattern: /कुतिया|कमीने/,
        category: 'hindi_indic',
        baseTerm: 'कुतिया',
        severity: 0.90,
      }
    );

    // Arabic native scripts
    this.rules.push({
      id: 'arabic_script_abuse',
      pattern: /(?:شرموطة|ابن الكلب|منيك|قحبة|عرص|كس امك)/,
      category: 'multilingual',
      baseTerm: 'arabic_abuse',
      severity: 0.98,
    });

    // Russian native scripts (Cyrillic)
    this.rules.push({
      id: 'cyrillic_script_abuse',
      pattern: /(?:сука|блять|хуй|пизда|пиздос|нахуй|ебать)/i,
      category: 'multilingual',
      baseTerm: 'cyrillic_abuse',
      severity: 0.98,
    });
  }

  /**
   * Adds custom user-defined blocked terms
   */
  public addBlockedTerms(terms: string[]): void {
    for (const t of terms) {
      if (t.trim()) {
        this.exactBlockedTerms.add(t.trim().toLowerCase());
      }
    }
  }

  /**
   * Adds user-defined exempt terms (safe words)
   */
  public addExemptTerms(terms: string[]): void {
    for (const t of terms) {
      if (t.trim()) {
        this.exemptTerms.add(t.trim().toLowerCase());
      }
    }
  }

  /**
   * Evaluates text for abuse across all languages and obfuscated structures.
   * Runs in microseconds without network or GPU dependency.
   */
  public detectAbuse(text: string, options: AbuseScanOptions = {}): AbuseAssessment {
    if (!text || !text.trim()) {
      return {
        isAbusive: false,
        confidence: 0,
        matchedTerms: [],
        source: 'pattern_obfuscated',
        explanation: 'Empty or whitespace text.',
      };
    }

    const raw = text.trim();
    const normalized = ObfuscationNormalizer.normalize(raw);
    const compact = ObfuscationNormalizer.stripSeparators(normalized);

    // 1. Check custom exempt words first
    if (options.exemptWords) {
      for (const ex of options.exemptWords) {
        if (normalized.includes(ex.toLowerCase())) {
          return {
            isAbusive: false,
            confidence: 0,
            matchedTerms: [],
            source: 'pattern_obfuscated',
            explanation: `Exempted by custom user safe rule: "${ex}".`,
          };
        }
      }
    }

    const matchedTerms: string[] = [];
    let maxSeverity = 0;

    // 2. Check custom blocked terms
    if (options.customWords) {
      for (const w of options.customWords) {
        const lowerW = w.toLowerCase().trim();
        if (lowerW && (normalized.includes(lowerW) || compact.includes(lowerW))) {
          matchedTerms.push(w);
          maxSeverity = Math.max(maxSeverity, 1.0);
        }
      }
    }

    // 3. Check Devanagari script patterns directly on raw/NFKD text
    for (const rule of this.devanagariRules) {
      if (rule.pattern.test(raw)) {
        matchedTerms.push(rule.baseTerm);
        maxSeverity = Math.max(maxSeverity, rule.severity);
      }
    }

    // 4. Tokenize and filter out known Scunthorpe false-positive safe words
    const tokens = normalized.split(/[^a-z0-9]+/i).filter(Boolean);
    const hasSafeWord = tokens.some((t) => SAFE_WORDS.has(t));

    // 5. Test obfuscation and multilingual rules against both raw, normalized, and compact forms
    for (const rule of this.rules) {
      const matchRaw = rule.pattern.test(raw);
      const matchNorm = rule.pattern.test(normalized);

      if (matchRaw || matchNorm) {
        // Scunthorpe protection check:
        // If the match was triggered inside a known safe word, inspect token context
        if (hasSafeWord && this.isFalsePositiveInSafeWord(raw, normalized, rule)) {
          continue;
        }

        matchedTerms.push(rule.baseTerm);
        maxSeverity = Math.max(maxSeverity, rule.severity);
      }
    }

    // 6. Direct compact check for heavily spaced/separated abuse (e.g. "m a d a r c h o d")
    if (matchedTerms.length === 0 && options.obfuscationDefense !== false) {
      const compactIndicRoots = ['madarchod', 'behenchod', 'bhenchod', 'bhosdike', 'chutiya', 'randi'];
      for (const root of compactIndicRoots) {
        if (compact.includes(root)) {
          matchedTerms.push(root);
          maxSeverity = Math.max(maxSeverity, 0.97);
          break;
        }
      }
    }

    const isAbusive = matchedTerms.length > 0;
    const confidence = isAbusive ? Math.min(1.0, maxSeverity) : 0.0;

    return {
      isAbusive,
      confidence,
      matchedTerms: Array.from(new Set(matchedTerms)),
      normalizedSample: normalized.length > 80 ? normalized.slice(0, 80) + '...' : normalized,
      source: isAbusive ? 'pattern_obfuscated' : 'multilingual_lexicon',
      explanation: isAbusive
        ? `Blocked abusive content (${matchedTerms.join(', ')}) with ${(confidence * 100).toFixed(0)}% confidence.`
        : 'No abusive language or obfuscated profanity detected.',
    };
  }

  /**
   * Helper to verify if an apparent match is actually part of an innocent safe word
   * e.g. "mature" matching "ma*ar", "assistant" matching "ass", etc.
   */
  private isFalsePositiveInSafeWord(raw: string, normalized: string, rule: AbuseRule): boolean {
    const rawLower = raw.toLowerCase();
    for (const safe of SAFE_WORDS) {
      if (rawLower.includes(safe) || normalized.includes(safe)) {
        // If the rule base term is "asshole" or "slur", but safe word is "pass" or "assistant", verify exact token
        if (rule.baseTerm === 'ma*ar' && (normalized.includes('mature') || normalized.includes('matter') || normalized.includes('match') || normalized.includes('matrix'))) {
          // If the text does NOT contain independent 'madar' or 'ma*ar', it's a false positive on mature/matter
          if (!/\bma[\s\*._\-\#@\$]+ar\b/i.test(normalized) && !/\bmadar/i.test(normalized)) {
            return true;
          }
        }
      }
    }
    return false;
  }
}
