/**
 * Laya Feed Control - Content Script Entrypoint
 * Operates across the whole web (<all_urls>)
 * Combines social feed controllers with real-time universal abuse guards.
 */

import { AdapterRegistry } from '../adapters/registry';
import { ExtensionSettings } from '../types';
import { FeedController } from './feed-controller';
import { AbuseGuard } from './abuse-guard';

const DEFAULT_SETTINGS: ExtensionSettings = {
  enabled: true,
  activeProfile: 'explore',
  pausedUntil: null,
  pausedSites: {},
  selectedTopics: [],
  topicMatchMode: 'ANY',
  strictness: 'balanced',
  keywordRules: [],
  creatorRules: [],
  misinformationEnabled: true,
  indiaPresetEnabled: true,
  minConfidenceThreshold: 0.75,
  allowUnverifiedClaims: true,
  aiContentFilter: 'allow_all',
  computeBackend: 'prefer_webgpu',
  modelInstalled: false,
  checkBeforeShowing: false,
  autoSkipShorts: true,
  maxConsecutiveSkips: 8,
  abuseFilterEnabled: true,
  abuseAction: 'blur',
  abuseStrictness: 'balanced',
  obfuscationDefense: true,
  multilingualAiScan: true,
  customAbuseWords: [],
  exemptAbuseWords: [],
};

function initContentScript() {
  const registry = new AdapterRegistry();
  const currentUrl = new URL(window.location.href);
  const { adapter, isGeneric } = registry.getAdapterForUrl(currentUrl);

  let feedController: FeedController | null = null;
  let abuseGuard: AbuseGuard | null = null;

  function applySettings(settings: ExtensionSettings) {
    // 1. Initialize or update universal abuse guard (runs on ANY website across the web)
    if (!abuseGuard) {
      abuseGuard = new AbuseGuard(settings);
      abuseGuard.start();
    } else {
      abuseGuard.updateSettings(settings);
    }

    // 2. Initialize or update social feed controller if adapter matches
    if (adapter) {
      if (!feedController) {
        feedController = new FeedController(adapter, settings);
        feedController.start();
      } else {
        feedController.updateSettings(settings);
      }
    }
  }

  if (typeof chrome !== 'undefined' && chrome.storage?.local) {
    chrome.storage.local.get(['layaSettings'], (result) => {
      const settings = (result.layaSettings as ExtensionSettings) || DEFAULT_SETTINGS;
      applySettings(settings);
    });

    // Listen for real-time settings changes
    chrome.storage.onChanged.addListener((changes, area) => {
      if (area === 'local' && changes.layaSettings) {
        applySettings(changes.layaSettings.newValue);
      }
    });

    // Listen for runtime commands (e.g. reveal item, pause)
    chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
      if (message.type === 'REVEAL_ITEM' && message.itemId) {
        feedController?.revealItem(message.itemId);
        sendResponse({ success: true });
      } else if (message.type === 'GET_PAGE_STATUS') {
        sendResponse({
          adapterName: adapter ? adapter.name : 'AbuseGuard (Whole Web)',
          isGeneric,
          url: currentUrl.href,
          abuseBlockedCount: abuseGuard ? abuseGuard.getBlockedCount() : 0,
        });
      }
    });
  } else {
    // Standalone / test fallback
    applySettings(DEFAULT_SETTINGS);
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initContentScript);
} else {
  initContentScript();
}
