/**
 * Laya Feed Control - X / Twitter Platform Adapter
 * Covers Timelines, Threads, and Embedded Media
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class TwitterAdapter extends BasePlatformAdapter {
  readonly name = 'twitter';
  readonly supportedRoutes = [
    /(?:www\.)?(?:twitter\.com|x\.com)\/(?:$|\?|home|explore|search|\w+\/status)/,
  ];

  public getFeedType(url: URL): FeedType {
    if (url.pathname.includes('/search')) {
      return 'search';
    }
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    return Array.from(root.querySelectorAll<HTMLElement>('article[data-testid="tweet"]'));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const textEl = element.querySelector<HTMLElement>('div[data-testid="tweetText"]');
    const text = textEl?.textContent?.trim() || '';

    // Author
    const userBlock = element.querySelector<HTMLElement>('div[data-testid="User-Name"]');
    const authorName = userBlock?.querySelector<HTMLElement>('span')?.textContent?.trim() || 'User';
    const handleEl = userBlock?.querySelector<HTMLAnchorElement>('a[href^="/"]');
    const authorHandle = handleEl?.getAttribute('href')?.replace(/^\//, '') || 'user';

    // Link & ID
    const statusLink = element.querySelector<HTMLAnchorElement>('a[href*="/status/"]');
    const href = statusLink?.getAttribute('href') || '';
    const idMatch = href.match(/\/status\/(\d+)/);
    const postId = idMatch ? idMatch[1] : `tw_${authorHandle}_${text.slice(0, 15)}`;

    if (!text && !element.querySelector('video, img')) return null;

    return {
      id: postId,
      url: href ? (href.startsWith('http') ? href : `https://x.com${href}`) : undefined,
      author: {
        name: authorName,
        handle: authorHandle,
      },
      text: text || 'Tweet Media',
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'text',
      element,
    };
  }
}
