/**
 * Laya Feed Control - Conservative Generic Platform Adapter
 * Only activates when containers pass strict semantic validation
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class GenericAdapter extends BasePlatformAdapter {
  readonly name = 'generic';
  // Matches any http/https URL as fallback
  readonly supportedRoutes = [/^https?:\/\/.+/];

  public getFeedType(url: URL): FeedType {
    return 'generic';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const candidates = Array.from(
      root.querySelectorAll<HTMLElement>(
        'article, div[role="article"], div[data-post-id], section.post-container'
      )
    );

    // Filter strictly to ensure legitimate post cards, avoiding navigation menus, sidebars, or headers
    return candidates.filter((el) => this.isValidPostContainer(el));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    if (!this.isValidPostContainer(element)) {
      return null;
    }

    // Title / Heading
    const headingEl = element.querySelector<HTMLElement>('h1, h2, h3, h4, .post-title');
    const heading = headingEl?.textContent?.trim() || '';

    // Paragraph text
    const paragraphs = Array.from(element.querySelectorAll<HTMLElement>('p, .post-content, .entry-content'));
    const bodyText = paragraphs.map((p) => p.textContent?.trim() || '').filter(Boolean).join(' ');

    const fullText = heading ? `${heading}. ${bodyText}` : bodyText;
    if (fullText.length < 25) {
      return null;
    }

    // Author
    const authorEl = element.querySelector<HTMLElement>('.author, [rel="author"], .byline');
    const authorName = authorEl?.textContent?.trim() || 'Author';

    const postId =
      element.getAttribute('data-post-id') ||
      element.getAttribute('id') ||
      `gen_${fullText.slice(0, 20).replace(/\W+/g, '_')}_${Math.random().toString(36).slice(2, 6)}`;

    return {
      id: postId,
      author: {
        name: authorName,
        handle: authorName.toLowerCase().replace(/\s+/g, '_'),
      },
      text: fullText,
      hashtags: this.extractHashtags(fullText),
      element,
    };
  }

  /**
   * Conservative heuristic: Requires semantic structure and non-trivial dimensions
   */
  private isValidPostContainer(element: HTMLElement): boolean {
    // Exclude header, footer, nav, aside elements or children of navigation
    if (element.closest('nav, header, footer, aside, .sidebar, .comments')) {
      return false;
    }

    // Must have at least one heading or paragraph
    const hasHeading = element.querySelector('h1, h2, h3, h4, h5, .title') !== null;
    const hasParagraph = element.querySelector('p, .text, .content') !== null;
    if (!hasHeading && !hasParagraph) {
      return false;
    }

    const textLength = element.textContent?.trim().length || 0;
    if (textLength < 30 || textLength > 10000) {
      return false;
    }

    return true;
  }
}
