/**
 * Laya Feed Control - Pinterest Platform Adapter
 * Covers Home, Search, and Grid Pin Feeds
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class PinterestAdapter extends BasePlatformAdapter {
  readonly name = 'pinterest';
  readonly supportedRoutes = [
    /(?:www\.)?pinterest\.(?:com|co\.uk|ca)\/(?:$|\?|search|today|ideas)/,
  ];

  public getFeedType(url: URL): FeedType {
    if (url.pathname.includes('/search')) return 'search';
    return 'grid';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div[data-test-id="pin"]',
      'div[data-grid-item="true"]',
      'div.Yl-.-interLayer-10',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const titleEl = element.querySelector<HTMLElement>(
      'h2, div[data-test-id="pin-title"], [data-test-id="rich-pin-title"]'
    );
    const title = titleEl?.textContent?.trim() || '';

    const descEl = element.querySelector<HTMLElement>('div[data-test-id="pin-description"], p');
    const desc = descEl?.textContent?.trim() || '';
    const fullText = title ? `${title}. ${desc}`.trim() : desc;

    if (!fullText) return null;

    // Creator
    const creatorEl = element.querySelector<HTMLElement>(
      'div[data-test-id="pin-creator-name"], div[data-test-id="user-rep"]'
    );
    const creatorName = creatorEl?.textContent?.trim() || 'Pinterest Creator';

    const linkEl = element.querySelector<HTMLAnchorElement>('a[href*="/pin/"]');
    const href = linkEl?.getAttribute('href') || '';
    const idMatch = href.match(/\/pin\/(\d+)/);
    const postId = idMatch ? idMatch[1] : `pin_${creatorName}_${fullText.slice(0, 15)}`;

    return {
      id: postId,
      url: href.startsWith('http') ? href : `https://www.pinterest.com${href}`,
      author: {
        name: creatorName,
        handle: creatorName.replace(/\s+/g, '_'),
      },
      text: fullText,
      hashtags: this.extractHashtags(fullText),
      mediaType: 'image',
      element,
    };
  }
}
