/**
 * Laya Feed Control - Platform Adapter Registry
 */

import { PlatformAdapter } from '../types';
import { YouTubeAdapter } from './youtube';
import { InstagramAdapter } from './instagram';
import { FacebookAdapter } from './facebook';
import { TwitterAdapter } from './twitter';
import { RedditAdapter } from './reddit';
import { LinkedInAdapter } from './linkedin';
import { TikTokAdapter } from './tiktok';
import { ThreadsAdapter } from './threads';
import { PinterestAdapter } from './pinterest';
import { BlueskyAdapter } from './bluesky';
import { GenericAdapter } from './generic';

export class AdapterRegistry {
  private dedicatedAdapters: PlatformAdapter[];
  private genericAdapter: PlatformAdapter;

  constructor() {
    this.dedicatedAdapters = [
      new YouTubeAdapter(),
      new InstagramAdapter(),
      new FacebookAdapter(),
      new TwitterAdapter(),
      new RedditAdapter(),
      new LinkedInAdapter(),
      new TikTokAdapter(),
      new ThreadsAdapter(),
      new PinterestAdapter(),
      new BlueskyAdapter(),
    ];
    this.genericAdapter = new GenericAdapter();
  }

  public getAdapterForUrl(url: URL, enableGeneric = true): { adapter: PlatformAdapter | null; isGeneric: boolean } {
    for (const adapter of this.dedicatedAdapters) {
      if (adapter.matches(url)) {
        return { adapter, isGeneric: false };
      }
    }

    if (enableGeneric) {
      return { adapter: this.genericAdapter, isGeneric: true };
    }

    return { adapter: null, isGeneric: false };
  }

  public getAllDedicated(): PlatformAdapter[] {
    return this.dedicatedAdapters;
  }
}
