/**
 * Laya Feed Control - LinkedIn Platform Adapter
 * Covers LinkedIn Feed and Shared Updates
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class LinkedInAdapter extends BasePlatformAdapter {
  readonly name = 'linkedin';
  readonly supportedRoutes = [
    /(?:www\.)?linkedin\.com\/(?:$|\?|feed|posts\/)/,
  ];

  public getFeedType(url: URL): FeedType {
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'div.feed-shared-update-v2',
      'div[data-urn*="urn:li:activity"]',
      'div.occludable-update',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    const textEl = element.querySelector<HTMLElement>(
      'div.feed-shared-update-v2__description, span.break-words, div.feed-shared-text'
    );
    const text = textEl?.textContent?.trim() || '';

    // Author
    const authorEl = element.querySelector<HTMLElement>(
      'span.feed-shared-actor__name, a[href*="/in/"] span[dir="ltr"]'
    );
    const authorName = authorEl?.textContent?.trim() || 'LinkedIn Member';
    const authorHandle = authorName.replace(/\s+/g, '_');

    const urn = element.getAttribute('data-urn') || '';
    const postId = urn || `li_${authorHandle}_${text.slice(0, 15)}`;

    if (!text) return null;

    return {
      id: postId,
      author: {
        name: authorName,
        handle: authorHandle,
      },
      text,
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'text',
      element,
    };
  }
}
