/**
 * Laya Feed Control - Feed Controller
 * Manages post lifecycle: Discovered -> Queued -> Checking -> Allowed | Hidden | Uncertain
 */

import {
  DecisionRecord,
  ExtensionSettings,
  ExtractedPost,
  PlatformAdapter,
} from '../types';
import { PolicyEngine } from '../engine/policy';
import { VideoSkipper } from './video-skipper';

export type PostState = 'Discovered' | 'Queued' | 'Checking' | 'Allowed' | 'Hidden' | 'Uncertain';

export interface ManagedItem {
  id: string;
  element: HTMLElement;
  state: PostState;
  post: ExtractedPost;
  contentHash: string;
  decision?: DecisionRecord;
}

export class FeedController {
  private adapter: PlatformAdapter;
  private settings: ExtensionSettings;
  private policyEngine: PolicyEngine;
  private videoSkipper: VideoSkipper;
  private items: Map<string, ManagedItem> = new Map();
  private elementToId: WeakMap<HTMLElement, string> = new WeakMap();
  private mutationObserver: MutationObserver | null = null;
  private intersectionObserver: IntersectionObserver | null = null;
  private revealedItemIds: Set<string> = new Set();
  private isProcessing = false;
  private queue: string[] = [];

  constructor(adapter: PlatformAdapter, settings: ExtensionSettings, policyEngine?: PolicyEngine) {
    this.adapter = adapter;
    this.settings = settings;
    this.policyEngine = policyEngine || new PolicyEngine();
    this.videoSkipper = new VideoSkipper({
      maxConsecutiveSkips: settings.maxConsecutiveSkips || 8,
    });
  }

  public start(): void {
    this.initIntersectionObserver();
    this.initMutationObserver();
    this.scanFeed(document.body);
  }

  public stop(): void {
    if (this.mutationObserver) {
      this.mutationObserver.disconnect();
      this.mutationObserver = null;
    }
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
      this.intersectionObserver = null;
    }
    this.restoreAllPosts();
    this.items.clear();
  }

  public updateSettings(newSettings: ExtensionSettings): void {
    this.settings = newSettings;
    // Re-evaluate existing items with new policy immediately without page reload!
    this.reEvaluateAll();
  }

  public revealItem(id: string): void {
    this.revealedItemIds.add(id);
    const item = this.items.get(id);
    if (item) {
      this.adapter.restorePost(item.element);
      item.state = 'Allowed';
    }
  }

  public restoreAllPosts(): void {
    for (const item of this.items.values()) {
      this.adapter.restorePost(item.element);
      item.state = 'Allowed';
    }
  }

  private initIntersectionObserver(): void {
    if (typeof IntersectionObserver === 'undefined') return;

    this.intersectionObserver = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            const id = this.elementToId.get(entry.target as HTMLElement);
            if (id) {
              const item = this.items.get(id);
              if (item && item.state === 'Discovered') {
                this.enqueueItem(id);
              }
            }
          }
        }
      },
      { rootMargin: '300px' } // Near-visible prefetch lookahead
    );
  }

  private initMutationObserver(): void {
    if (typeof MutationObserver === 'undefined') return;

    this.mutationObserver = new MutationObserver((mutations) => {
      let shouldScan = false;
      for (const mut of mutations) {
        // Ignore changes made by Laya's own hiding
        if (mut.type === 'childList' && mut.addedNodes.length > 0) {
          for (let i = 0; i < mut.addedNodes.length; i++) {
            const node = mut.addedNodes[i];
            if (node instanceof HTMLElement && !node.classList.contains('laya-hidden-post')) {
              shouldScan = true;
              break;
            }
          }
        }
      }
      if (shouldScan) {
        this.scanFeed(document.body);
      }
    });

    this.mutationObserver.observe(document.body, {
      childList: true,
      subtree: true,
    });
  }

  public scanFeed(root: Element): void {
    const containers = this.adapter.findPostContainers(root);
    for (const el of containers) {
      if (this.elementToId.has(el)) continue;

      const post = this.adapter.extractContent(el);
      if (!post) continue;

      const item: ManagedItem = {
        id: post.id,
        element: el,
        state: 'Discovered',
        post,
        contentHash: post.id + post.text.length,
      };

      this.items.set(post.id, item);
      this.elementToId.set(el, post.id);

      if (this.intersectionObserver) {
        this.intersectionObserver.observe(el);
      } else {
        this.enqueueItem(post.id);
      }
    }
  }

  private enqueueItem(id: string): void {
    const item = this.items.get(id);
    if (!item || item.state !== 'Discovered') return;

    item.state = 'Queued';
    this.queue.push(id);
    this.processQueue();
  }

  private async processQueue(): Promise<void> {
    if (this.isProcessing || this.queue.length === 0) return;
    this.isProcessing = true;

    while (this.queue.length > 0) {
      const id = this.queue.shift();
      if (!id) continue;

      const item = this.items.get(id);
      if (!item) continue;

      item.state = 'Checking';

      // Evaluate policy
      await this.evaluateItem(item);
    }

    this.isProcessing = false;
  }

  private async evaluateItem(item: ManagedItem): Promise<void> {
    const detectedTopics = this.detectBasicTopics(item.post.text);

    const decision = this.policyEngine.evaluate(
      {
        post: item.post,
        hostname: window.location.hostname,
        detectedTopics,
        revealedItemIds: this.revealedItemIds,
      },
      this.settings
    );

    item.decision = decision;

    const feedType = this.adapter.getFeedType(new URL(window.location.href));

    if (decision.action === 'HIDE') {
      item.state = 'Hidden';

      if (feedType === 'shorts') {
        // Vertical Short-form video skipping!
        await this.videoSkipper.handleBlockedVideo(item.element, this.adapter, decision.explanation);
      } else {
        // Standard feed collapse
        this.adapter.hidePost(item.element, decision.explanation);
      }

      // Record to history via chrome message if available
      this.sendDecisionToBackground(decision, item.post);
    } else {
      item.state = 'Allowed';
      this.adapter.restorePost(item.element);
      if (feedType === 'shorts') {
        this.videoSkipper.resetStreak();
      }
    }
  }

  private reEvaluateAll(): void {
    for (const item of this.items.values()) {
      this.evaluateItem(item);
    }
  }

  private detectBasicTopics(text: string): string[] {
    const lower = text.toLowerCase();
    const topics: string[] = [];

    const topicKeywords: Record<string, string[]> = {
      education: ['learn', 'tutorial', 'course', 'student', 'school', 'study', 'education', 'lecture'],
      mathematics: ['calculus', 'algebra', 'equation', 'math', 'derivative', 'integral', 'matrix'],
      science: ['physics', 'chemistry', 'biology', 'astronomy', 'quantum', 'experiment', 'nasa'],
      technology: ['software', 'hardware', 'tech', 'computer', 'device', 'gadget', 'silicon'],
      programming: ['javascript', 'python', 'typescript', 'react', 'code', 'coding', 'github', 'developer'],
      business: ['finance', 'market', 'stock', 'investing', 'economy', 'startup', 'revenue'],
      news: ['breaking', 'report', 'press', 'journalist', 'investigation', 'parliament', 'senate'],
      entertainment: ['movie', 'trailer', 'song', 'comedy', 'funny', 'music', 'gameplay', 'gaming'],
      sports: ['cricket', 'football', 'fifa', 'nba', 'tennis', 'match', 'tournament', 'championship'],
      art: ['painting', 'drawing', 'illustration', 'sketch', 'sculpture', 'design', 'gallery'],
      travel: ['travel', 'flight', 'hotel', 'destination', 'island', 'vacation', 'mountains'],
    };

    for (const [topicId, words] of Object.entries(topicKeywords)) {
      if (words.some((w) => lower.includes(w))) {
        topics.push(topicId);
      }
    }

    return topics;
  }

  private sendDecisionToBackground(decision: DecisionRecord, post: ExtractedPost): void {
    if (typeof chrome !== 'undefined' && chrome.runtime?.sendMessage) {
      try {
        chrome.runtime.sendMessage({
          type: 'RECORD_DECISION',
          payload: {
            ...decision,
            snippet: post.text.slice(0, 140),
            authorName: post.author?.name,
            authorHandle: post.author?.handle,
          },
        });
      } catch {}
    }
  }
}
