/**
 * Laya Feed Control - Instagram Platform Adapter
 * Covers Feed, Explore, and Reels
 */

import { ExtractedPost, FeedType } from '../types';
import { BasePlatformAdapter } from './base';

export class InstagramAdapter extends BasePlatformAdapter {
  readonly name = 'instagram';
  readonly supportedRoutes = [
    /(?:www\.)?instagram\.com\/(?:$|\?|explore|reels|reel\/|p\/)/,
  ];

  public getFeedType(url: URL): FeedType {
    if (url.pathname.includes('/reels') || url.pathname.includes('/reel/')) {
      return 'shorts';
    }
    if (url.pathname.includes('/explore')) {
      return 'grid';
    }
    return 'feed';
  }

  public findPostContainers(root: Element | Document): HTMLElement[] {
    const selectors = [
      'article', // Main feed post
      'div[role="dialog"] article',
      'div.x1lliihq.x1n2onr6.xh8yej3', // Modern Instagram feed card
      'div[data-testid="post-container"]',
    ];
    return Array.from(root.querySelectorAll<HTMLElement>(selectors.join(', ')));
  }

  public extractContent(element: HTMLElement): ExtractedPost | null {
    // Caption / Description
    const captionEl = element.querySelector<HTMLElement>(
      'h1, span._a9zs, div._a9zs, div.x78zum5.xdt5ytf span, ul li div span'
    );
    const text = captionEl?.textContent?.trim() || '';

    // Author
    const authorEl = element.querySelector<HTMLElement>(
      'header a, span._aacl._aaco._aacw._aacx, a.x1i10hfl.xjqpnuy'
    );
    const authorHandle = authorEl?.textContent?.trim().replace(/^@/, '') || 'unknown';

    // Link
    const linkEl = element.querySelector<HTMLAnchorElement>('a[href*="/p/"], a[href*="/reel/"]');
    const href = linkEl?.getAttribute('href') || '';
    const idMatch = href.match(/\/(?:p|reel)\/([a-zA-Z0-9_-]+)/);
    const postId = idMatch ? idMatch[1] : `ig_${authorHandle}_${text.slice(0, 15)}`;

    if (!text && !postId) return null;

    return {
      id: postId,
      url: href.startsWith('http') ? href : `https://www.instagram.com${href}`,
      author: {
        name: authorHandle,
        handle: authorHandle,
      },
      text: text || 'Instagram Post',
      hashtags: this.extractHashtags(text),
      mediaType: element.querySelector('video') ? 'video' : 'image',
      element,
    };
  }

  public async advanceShort(currentElement: HTMLElement): Promise<boolean> {
    this.pauseMedia(currentElement);
    this.dispatchArrowDown();
    return true;
  }
}
