/**
 * Laya Feed Control - Real-Time Universal Abuse & Profanity Guard
 * Scans comments, forum posts, and text blocks across the whole web (<all_urls>)
 * Blocks/blurs obfuscated words (e.g. "ma*ar", "m@d@r", "f*ck", "ch**iya") in real time.
 */

import { AbuseDetector } from '../engine/abuse-detector';
import { AdultContentDetector } from '../engine/adult-detector';
import { ExtensionSettings } from '../types';

export class AbuseGuard {
  private detector: AbuseDetector;
  private adultDetector: AdultContentDetector;
  private settings: ExtensionSettings;
  private observer: MutationObserver | null = null;
  private processedElements: WeakSet<Element> = new WeakSet();
  private blockedCount = 0;
  private scanDebounceTimer: number | null = null;
  private pendingNodes: Element[] = [];

  constructor(settings: ExtensionSettings) {
    this.settings = settings;
    this.detector = new AbuseDetector();
    this.adultDetector = new AdultContentDetector();
    this.applySettingsToDetector();
  }

  private applySettingsToDetector(): void {
    if (this.settings.customAbuseWords?.length) {
      this.detector.addBlockedTerms(this.settings.customAbuseWords);
    }
    if (this.settings.exemptAbuseWords?.length) {
      this.detector.addExemptTerms(this.settings.exemptAbuseWords);
    }
  }

  public updateSettings(newSettings: ExtensionSettings): void {
    this.settings = newSettings;
    this.applySettingsToDetector();
    if (!this.settings.abuseFilterEnabled) {
      this.restoreAll();
    } else {
      this.scanDocument();
    }
  }

  public start(): void {
    if (!this.settings.abuseFilterEnabled) return;
    this.injectStyles();
    this.scanDocument();
    this.initObserver();
  }

  public stop(): void {
    if (this.observer) {
      this.observer.disconnect();
      this.observer = null;
    }
    this.restoreAll();
  }

  private injectStyles(): void {
    const doc = typeof document !== 'undefined' ? document : null;
    if (!doc || doc.getElementById('laya-abuse-guard-styles')) return;

    const style = doc.createElement('style');
    style.id = 'laya-abuse-guard-styles';
    style.textContent = `
      .laya-abuse-container {
        position: relative !important;
      }
      .laya-abuse-blurred {
        filter: blur(6px) !important;
        opacity: 0.45 !important;
        user-select: none !important;
        pointer-events: none !important;
        transition: filter 0.2s ease, opacity 0.2s ease !important;
      }
      .laya-abuse-revealed {
        filter: none !important;
        opacity: 1 !important;
        pointer-events: auto !important;
        user-select: auto !important;
      }
      .laya-abuse-badge {
        display: inline-flex !important;
        align-items: center !important;
        gap: 6px !important;
        padding: 4px 10px !important;
        margin: 4px 0 !important;
        background: #181a20 !important;
        color: #f87171 !important;
        border: 1px solid rgba(239, 68, 68, 0.35) !important;
        border-radius: 6px !important;
        font-family: system-ui, -apple-system, sans-serif !important;
        font-size: 11px !important;
        font-weight: 600 !important;
        cursor: pointer !important;
        user-select: none !important;
        z-index: 10 !important;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4) !important;
      }
      .laya-abuse-badge:hover {
        background: #232730 !important;
        border-color: #ef4444 !important;
      }
    `;
    doc.head?.appendChild(style);
  }

  private initObserver(): void {
    if (typeof MutationObserver === 'undefined' || typeof document === 'undefined') return;

    this.observer = new MutationObserver((mutations) => {
      let shouldScan = false;
      for (const m of mutations) {
        if (m.type === 'childList' && m.addedNodes.length > 0) {
          for (let i = 0; i < m.addedNodes.length; i++) {
            const node = m.addedNodes[i];
            if (node.nodeType === 1) { // ELEMENT_NODE
              this.pendingNodes.push(node as Element);
              shouldScan = true;
            }
          }
        }
      }

      if (shouldScan) {
        this.scheduleScan();
      }
    });

    this.observer.observe(document.body || document.documentElement, {
      childList: true,
      subtree: true,
    });
  }

  private scheduleScan(): void {
    if (this.scanDebounceTimer !== null) return;

    const runner = () => {
      this.scanDebounceTimer = null;
      const batch = this.pendingNodes.splice(0, 50);
      for (const root of batch) {
        this.scanElementTree(root);
      }
      if (this.pendingNodes.length > 0) {
        this.scheduleScan();
      }
    };

    if (typeof requestIdleCallback !== 'undefined') {
      this.scanDebounceTimer = requestIdleCallback(runner, { timeout: 250 }) as unknown as number;
    } else {
      this.scanDebounceTimer = setTimeout(runner, 50) as unknown as number;
    }
  }

  public scanDocument(): void {
    if (typeof document === 'undefined') return;
    this.scanElementTree(document.body || document.documentElement);
  }

  /**
   * Scans an element and its descendants for comments and text blocks
   */
  public scanElementTree(root: Element | null): void {
    if (!root || this.processedElements.has(root)) return;

    const candidateSelectors = [
      // Known platform comment containers
      '#content-text', // YouTube comment
      'ytd-comment-view-model',
      'shreddit-comment', // Reddit modern comment
      '[data-testid="comment"]',
      '[data-testid="tweetText"]', // Twitter/X post & reply text
      'ul._a9ym', // Instagram comment
      'span._a9zs', // Instagram comment text
      '[data-e2e="comment-level-1"]', // TikTok comment
      // Universal comment & forum elements on any website
      '.comment',
      '.comments',
      '.comment-body',
      '.comment-content',
      '.comment-text',
      '.reply',
      '.forum-post',
      '.message-content',
      'blockquote',
      'p',
      'li',
      'span',
    ];

    // Check matching descendants bottom-up (deepest first)
    try {
      const candidates = Array.from(root.querySelectorAll(candidateSelectors.join(', ')));
      for (let i = candidates.length - 1; i >= 0; i--) {
        this.inspectElement(candidates[i]);
      }

      // Also inspect the root element itself if applicable
      this.inspectElement(root);
    } catch {
      // Ignore DOM selector errors on unusual elements
    }
  }

  /**
   * Evaluates a single DOM element for abusive language
   */
  public inspectElement(el: Element): boolean {
    if (this.processedElements.has(el)) return false;

    // Skip input fields, code blocks, script/style, or elements already handled
    const tag = el.tagName.toLowerCase();
    if (['script', 'style', 'textarea', 'input', 'code', 'pre', 'noscript'].includes(tag)) {
      this.processedElements.add(el);
      return false;
    }

    if (el.classList.contains('laya-abuse-badge') || el.classList.contains('laya-abuse-blurred')) {
      return false;
    }

    // If element is already inside a blocked container, skip to avoid double-blocking
    if (el.closest('.laya-abuse-blurred, [data-laya-abuse-detected="true"]')) {
      this.processedElements.add(el);
      return false;
    }

    // If element already contains a blocked child, skip parent container
    if (el.querySelector('.laya-abuse-blurred, [data-laya-abuse-detected="true"]')) {
      this.processedElements.add(el);
      return false;
    }

    // Only inspect leaf or direct text containers to prevent over-hiding whole pages
    const text = el.textContent?.trim();
    if (!text || text.length < 2 || text.length > 5000) {
      return false;
    }

    // Check direct children: if element has children that could be scanned individually, skip parent
    if (el.children.length > 0 && Array.from(el.children).some((c) => ['p', 'span', 'div', 'blockquote'].includes(c.tagName.toLowerCase()))) {
      return false;
    }

    const assessment = this.detector.detectAbuse(text, {
      strictness: this.settings.abuseStrictness || 'balanced',
      obfuscationDefense: this.settings.obfuscationDefense !== false,
      customWords: this.settings.customAbuseWords,
      exemptWords: this.settings.exemptAbuseWords,
    });

    if (assessment.isAbusive) {
      this.blockAbusiveElement(el as HTMLElement, assessment.matchedTerms, 'Abusive comment');
      this.processedElements.add(el);
      return true;
    }

    // Intrinsic adult / NSFW content safety check
    const adultCheck = this.adultDetector.detectAdultContent(text);
    if (adultCheck.isAdult) {
      this.blockAbusiveElement(el as HTMLElement, adultCheck.matchedPatterns, 'Adult content');
      this.processedElements.add(el);
      return true;
    }

    this.processedElements.add(el);
    return false;
  }

  /**
   * Applies the configured blocking action (blur, hide, or redact) to an abusive or explicit element
   */
  private blockAbusiveElement(el: HTMLElement, matchedTerms: string[], categoryLabel: string = 'Abusive content'): void {
    this.blockedCount++;
    el.setAttribute('data-laya-abuse-detected', 'true');
    el.setAttribute('data-laya-abuse-terms', matchedTerms.join(', '));

    const action = this.settings.abuseAction || 'blur';

    if (action === 'hide') {
      (el as any)._layaPrevDisplay = el.style.display;
      el.style.display = 'none';
      return;
    }

    if (action === 'redact') {
      this.redactTextContent(el, matchedTerms);
      return;
    }

    // Default action: 'blur' with interactive sovereign reveal badge
    el.classList.add('laya-abuse-blurred');
    el.parentElement?.classList.add('laya-abuse-container');

    const badge = el.ownerDocument.createElement('div');
    badge.className = 'laya-abuse-badge';
    badge.setAttribute('role', 'button');
    badge.setAttribute('tabindex', '0');
    badge.setAttribute('title', `Blocked: ${matchedTerms.join(', ')}. Click to toggle view.`);
    badge.innerHTML = `🛡️ ${categoryLabel} hidden by Laya (${matchedTerms[0] || 'blocked'}) • Click to view`;

    badge.addEventListener('click', (e) => {
      e.stopPropagation();
      const isBlurred = el.classList.contains('laya-abuse-blurred');
      if (isBlurred) {
        el.classList.remove('laya-abuse-blurred');
        el.classList.add('laya-abuse-revealed');
        badge.innerHTML = `🛡️ ${categoryLabel} revealed • Click to re-hide`;
      } else {
        el.classList.add('laya-abuse-blurred');
        el.classList.remove('laya-abuse-revealed');
        badge.innerHTML = `🛡️ ${categoryLabel} hidden by Laya • Click to view`;
      }
    });

    el.insertAdjacentElement('beforebegin', badge);

    // Notify background worker of blocked abuse count
    this.notifyBackgroundBlocked(matchedTerms);
  }

  private redactTextContent(el: HTMLElement, _matchedTerms: string[]): void {
    // Redact text nodes in place
    const walker = el.ownerDocument.createTreeWalker(el, 4 /* NodeFilter.SHOW_TEXT */);
    let node: Node | null;
    while ((node = walker.nextNode())) {
      const val = node.nodeValue;
      if (val) {
        const assessment = this.detector.detectAbuse(val);
        if (assessment.isAbusive) {
          node.nodeValue = '[Blocked by Laya Abuse Guard]';
        }
      }
    }
  }

  private notifyBackgroundBlocked(matchedTerms: string[]): void {
    if (typeof chrome !== 'undefined' && chrome.runtime?.sendMessage) {
      try {
        chrome.runtime.sendMessage({
          type: 'ABUSE_BLOCKED',
          count: 1,
          url: typeof window !== 'undefined' ? window.location.href : '',
          terms: matchedTerms,
        });
      } catch {
        // Extension context might be disconnected
      }
    }
  }

  private restoreAll(): void {
    if (typeof document === 'undefined') return;

    // Restore blurred elements
    const blurred = document.querySelectorAll('.laya-abuse-blurred, .laya-abuse-revealed');
    blurred.forEach((el) => {
      el.classList.remove('laya-abuse-blurred', 'laya-abuse-revealed');
    });

    // Remove badges
    const badges = document.querySelectorAll('.laya-abuse-badge');
    badges.forEach((b) => b.remove());

    // Restore hidden elements
    const hidden = document.querySelectorAll('[data-laya-abuse-detected="true"]');
    hidden.forEach((el) => {
      const h = el as HTMLElement;
      if ((h as any)._layaPrevDisplay !== undefined) {
        h.style.display = (h as any)._layaPrevDisplay;
      }
      h.removeAttribute('data-laya-abuse-detected');
    });

    this.processedElements = new WeakSet();
  }

  public getBlockedCount(): number {
    return this.blockedCount;
  }
}
